import accredit_dialog_view from './accredit_dialog_extend'
export default {
  // 多租户——租户管理——授权按钮
  role_authorization_extend_views: {
    selector: {
      attr: 'id',
      value: 'tenant_management_menu_table_main_table'
    },
    type: 'custom',
    beforeOperate: (app, operateItem, options) => {
      let ops = options.element.columns.find((item) => item.prop === 'operate')
      let accreditObj = ops?.btns?.find(
        (item) => item.customAction === 'authorization'
      )
      if (accreditObj) {
        accreditObj.click = (vm, rowData) => {
          // 弹窗节点已存在
          let tenant_management_menu_accredit_dialog = vm.$select(
            vm.$ds.idPre + 'tenant_management_menu_accredit_dialog'
          )
          if (tenant_management_menu_accredit_dialog?.instance) {
            tenant_management_menu_accredit_dialog.$ds.mainTableRowData =
              rowData.row
            tenant_management_menu_accredit_dialog.data.display = true
            return
          }

          let accreditDiolg = window.Tech._cloneDeep(operateItem.view)
          accreditDiolg.dataSource.mainTableRowData = rowData.row
          accreditDiolg.display = true

          // 弹窗节点不存在，动态添加弹窗
          vm.$cmd.meta.popupView(vm, accreditDiolg, vm.$ds.idPre)
        }
      }
      return operateItem.view
    },
    view: accredit_dialog_view
  },
  // 多租户——租户管理——表格视图——'是否启用列'支持切换
  tenant_management_menu_grid_main_table_isEnable_extend_views: {
    selector: {
      attr: 'id',
      value: 'tenant_management_menu_table_main_table_column_isEnable'
    },
    beforeOperate: (app, operateItem, options) => {
      let enableSwitch = options.element
      options.element.formatItem = (row, item) => {
        // 系统租户 禁用开关
        if (row.id === 'rbac_tenant_root') {
          item.disabled = true
        } else {
          item.disabled = false
        }
        return item
      }
      options.element.bind_on_changeHandler = async (options) => {
        const { self: vm } = options
        let params = {
          args: {
            ids: [options.value.row.id],
            values: {
              isEnable: options.value.row.isEnable,
              id: options.value.row.id
            }
          },
          context: {
            uid: '',
            lang: window.Tech?.LANG?.locale || 'zh_CN'
          },
          model: 'rbac_tenant',
          // service: 'sie-snest-tenant.rbac_tenant.rbac_tenant_ext_form.form:master#update',
          service: 'update',
          tag: 'master',
          app: 'sie-iidp-tenant'
        }
        window.Tech.httpMeta({
          data: {
            params
          }
        })
          .then((res) => {
            // 刷新
            const refreshBtn = vm.$select(
              vm.$ds.idPre + 'table_main_toolbar_refresh'
            )
            refreshBtn?.instance?.click()
          })
          .catch((err) => {
            console.log(err)
            const refreshBtn = vm.$select(
              vm.$ds.idPre + 'table_main_toolbar_refresh'
            )
            refreshBtn?.instance?.click()
          })
      }
    }
  }
}
