  // 租户用户-详情-设置角色弹窗表格请求接口替换
  user_menu_tab_role_ids_dialog_pop_select_table_extend_view: {
    selector: {
      attr: 'id',
      value: 'user_menu_tab_role_ids_dialog_pop_select_table'
    },
    beforeOperate: (app, operateItem, options) => {
      let tableDataDsConfigs = options.element.ds_config.list.find(
        (item) => item.name === 'tablePopData'
      )
      let tableCountDsConfigs = options.element.ds_config.list.find(
        (item) => item.name === 'tableDataCount'
      )
      tableDataDsConfigs.reqPrep = operateItem.view.ds_config.list[0].reqPrep
      tableCountDsConfigs.reqPrep = operateItem.view.ds_config.list[1].reqPrep
    },
    view: {
      ds_config: {
        list: [
          {
            name: 'tablePopData',
            reqPrep: (vm, params, config) => {
              const detailVm = vm.$select(vm.$ds.idPre + 'table_detail')
              if (detailVm.$ds.clickType !== 'add') {
                params.params.args.filter = vm.$cmd.meta.addSearch(
                  params.params.args.filter,
                  [
                    [
                      'tenant_id',
                      '=',
                      detailVm.$ds.mainTableRowData.tenant_id.id
                    ]
                  ]
                )
              }
              params.params.service = 'searchTenantRole'
              params.params.args.filter = vm.$cmd.meta.addSearch(
                params.params.args.filter,
                [['roleType', '=', '1']]
              )
              return params
            }
          },
          {
            name: 'tableDataCount',
            reqPrep: (vm, params, config) => {
              const detailVm = vm.$select(vm.$ds.idPre + 'table_detail')
              if (detailVm.$ds.clickType !== 'add') {
                params.params.args.filter = vm.$cmd.meta.addSearch(
                  params.params.args.filter,
                  [
                    [
                      'tenant_id',
                      '=',
                      detailVm.$ds.mainTableRowData.tenant_id.id
                    ]
                  ]
                )
              }
              params.params.service = 'countTenantRole'
              params.params.args.filter = vm.$cmd.meta.addSearch(
                params.params.args.filter,
                [['roleType', '=', '1']]
              )
              return params
            }
          }
        ]
      }
    }
  },
