// 多租户——租户管理——授权弹框
export default {
  type: 'dialog',
  id: 'tenant_management_menu_accredit_dialog',
  width: '525px',
  title: Tech.$t('tenant.power'),
  display: false,
  ds_config: {
    list: [
      {
        type: 'meta', // 调用元模型引擎API获取数据
        name: 'treeData', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
        autoRequest: true, // 在节点渲染后，是否自动触发请求，默认false
        options: {
          params: {
            // 参考元模型api传参规范
            args: {
              useDisplayForModel: true,
              limit: 0,
              offset: 0,
              order: '',
              filter: [['type', 'in', ['ProductLine', 'Menu']]],
              properties: ['name', 'code', 'model', 'type', 'parent'],
              bind_id: '$ds.mainTableRowData.id'
            },
            model: 'rbac_tenant',
            tag: 'master',
            service: 'listPermission',
            app: 'sie-iidp-tenant'
          }
        },
        reqAfter: (vm, res, config) => {
          return res.data?.map((item) => ({
            id: item.id,
            name: item.name,
            code: item.code,
            disabled: vm.$ds.clickType === 'preview',
            isLeafMenu: item.isLeafMenu,
            icons: item.isLeafMenu
              ? [
                  {
                    icon: 'el-icon-edit',
                    type: 'edit'
                  }
                ]
              : null,
            parentId:
              typeof item.parent === 'object' && item.parent !== null
                ? item.parent.value
                : item.parent
          }))
        }
      },
      {
        type: 'meta', // 调用元模型引擎API获取数据
        name: 'checkedKeys', // 数据源标识，获取数据后将根据此名称存入dataSource.data1中
        autoRequest: true, // 在节点渲染后，是否自动触发请求，默认false
        options: {
          params: {
            args: {
              bind_id: '$ds.mainTableRowData.id'
            },
            model: 'rbac_tenant',
            tag: 'master',
            service: 'listGrant',
            app: 'sie-iidp-tenant'
          }
        },
        reqAfter: (vm, res, config) => {
          const _submitKeys = res.data?.map((item) => item)
          vm.$ds.submitKeys = _submitKeys
          return _submitKeys
        }
      },
      {
        type: 'meta',
        name: 'dataSave',
        options: {
          params: {
            args: {
              bind_id: '$ds.mainTableRowData.id',
              bind_permissionIds: '$ds.submitKeys'
            },
            model: 'rbac_tenant',
            tag: 'master',
            service: 'grant',
            app: 'sie-iidp-tenant'
          }
        }
      }
    ]
  },
  dataSource: {
    treeData: [],
    checkedKeys: [],
    submitKeys: []
  },
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      let loadingInstance = null
      loadingInstance = window.ELEMENT.Loading.service({
        text: Tech.$t('tenant.beSaving')
      })
      const data = await params.self.request('dataSave', {})
      loadingInstance.close()

      if (data?.response?.data?.error?.message || data?.error?.message) {
        window.ELEMENT.Message.warning(
          data?.response?.data?.error?.message || data?.error?.message
        )
      } else {
        // 等loading关闭后等一会再提醒
        setTimeout(() => {
          window.ELEMENT.Message.success(Tech.$t('common.saveSuccess'))
        }, 500)
        value.close()
      }
    }
  },
  items: [
    {
      type: 'container',
      id: 'role_data_action_scope_box',
      className: 'role_data_action_scope_box',
      style: {
        height: '100%'
      },
      css: `
                  #role_data_action_scope_box .el-input-group__append {
                    background: var(--button-primary-bg, #677177) !important;
                  }
                  #role_data_action_scope_box .appendDisabled {
                     color: #fff !important
                   }
                   .role_data_action_scope_box .el-tree-node>.el-tree-node__content {
                       background-color: unset;
                     }
                  `,

      items: [
        {
          type: 'container',
          style: {
            overflowY: 'auto',
            display: 'flex'
          },
          css: `
            #tenant_management_menu_tenant_management_menu_accredit_dialog .ii-tree .ii-tree-wrap .ii-tree-main{
              overflow-x: hidden;
              padding-right: 25px;
            }
            #tenant_management_menu_tenant_management_menu_accredit_dialog .choice-dialog .body{
              padding-right: 0px;
              padding-left: 25px;
            }
            #tenant_management_menu_tenant_management_menu_accredit_dialog .choice-dialog .footer{
              padding-right: 28px;
            }
          `,
          items: [
            {
              type: 'tree',
              style: {
                width: '500px',
                flexShrink: 0,
                height: '400px'
              },
              toolbarStyle: {
                border: 0
              },
              isPermission: true, // 启用权限模式
              bind_curCheckedKeys: '$ds.checkedKeys',
              transformTotree: true,
              appendText: true,
              toolbarConfig: {
                search: {
                  showInput: true
                }
              },
              treeConfig: {
                showTree: true,
                nodeKey: 'id',
                delUnParent: true
              },
              bind_data: '$ds.treeData',
              bind_on_nodeExpand: (params) => {
                let node = params?.value?.target?.$el
                if (node) {
                  setTimeout(() => {
                    node?.scrollIntoView({
                      behavior: 'smooth',
                      block: 'center'
                    })
                  }, 200)
                }
              },
              bind_on_check: (params) => {
                params.self.$ds.submitKeys =
                  params.value.checked.checkedKeys.slice()
              }
            }
          ]
        }
      ]
    }
  ]
}
